  1	import Foundation
  2	
  3	public enum BedtimeConstants {
  4	    public static let machServiceName = "com.ntfy.bedtime.daemon"
  5	    public static let daemonPlistName = "com.ntfy.bedtime.daemon.plist"
  6	    public static let agentPlistName = "com.ntfy.bedtime.agent.plist"
  7	}
  8	
  9	public struct ScheduleConfiguration: Codable, Equatable {
 10	    public var enabled: Bool
 11	    public var bedtimeHour: Int
 12	    public var bedtimeMinute: Int
 13	    public var allowedHour: Int
 14	    public var allowedMinute: Int
 15	    /// Calendar weekdays: Sunday = 1, Saturday = 7. Days refer to bedtime.
 16	    public var activeWeekdays: [Int]
 17	    public var firstWarningSeconds: Int
 18	    public var finalWarningSeconds: Int
 19	
 20	    public init(enabled: Bool = false, bedtimeHour: Int = 22, bedtimeMinute: Int = 0,
 21	                allowedHour: Int = 7, allowedMinute: Int = 0,
 22	                activeWeekdays: [Int] = [1, 2, 3, 4, 5],
 23	                firstWarningSeconds: Int = 900, finalWarningSeconds: Int = 300) {
 24	        self.enabled = enabled
 25	        self.bedtimeHour = bedtimeHour
 26	        self.bedtimeMinute = bedtimeMinute
 27	        self.allowedHour = allowedHour
 28	        self.allowedMinute = allowedMinute
 29	        self.activeWeekdays = activeWeekdays
 30	        self.firstWarningSeconds = firstWarningSeconds
 31	        self.finalWarningSeconds = finalWarningSeconds
 32	    }
 33	
 34	    private enum CodingKeys: String, CodingKey {
 35	        case enabled, bedtimeHour, bedtimeMinute, allowedHour, allowedMinute, activeWeekdays
 36	        case firstWarningSeconds, finalWarningSeconds
 37	    }
 38	
 39	    public init(from decoder: Decoder) throws {
 40	        let values = try decoder.container(keyedBy: CodingKeys.self)
 41	        enabled = try values.decode(Bool.self, forKey: .enabled)
 42	        bedtimeHour = try values.decode(Int.self, forKey: .bedtimeHour)
 43	        bedtimeMinute = try values.decode(Int.self, forKey: .bedtimeMinute)
 44	        allowedHour = try values.decode(Int.self, forKey: .allowedHour)
 45	        allowedMinute = try values.decode(Int.self, forKey: .allowedMinute)
 46	        activeWeekdays = try values.decode([Int].self, forKey: .activeWeekdays)
 47	        firstWarningSeconds = try values.decodeIfPresent(Int.self, forKey: .firstWarningSeconds) ?? 900
 48	        finalWarningSeconds = try values.decodeIfPresent(Int.self, forKey: .finalWarningSeconds) ?? 300
 49	    }
 50	
 51	    public func validated() throws -> Self {
 52	        guard (0...23).contains(bedtimeHour), (0...23).contains(allowedHour),
 53	              (0...59).contains(bedtimeMinute), (0...59).contains(allowedMinute),
 54	              bedtimeHour != allowedHour || bedtimeMinute != allowedMinute,
 55	              !activeWeekdays.isEmpty, activeWeekdays.allSatisfy({ (1...7).contains($0) }),
 56	              Set(activeWeekdays).count == activeWeekdays.count else {
 57	            throw BedtimeError.message("Choose different start/end times and at least one active day.")
 58	        }
 59	        guard finalWarningSeconds > 0, firstWarningSeconds > finalWarningSeconds,
 60	              firstWarningSeconds <= 86400 else {
 61	            throw BedtimeError.message("The first warning must be earlier than the final warning, both before bedtime, and at most 24 hours ahead.")
 62	        }
 63	        return self
 64	    }
 65	}
 66	
 67	public enum BedtimeError: LocalizedError {
 68	    case message(String)
 69	    public var errorDescription: String? {
 70	        switch self { case .message(let message): return message }
 71	    }
 72	}
 73	
 74	public enum PolicyPhase: String, Codable {
 75	    case allowed, blocked, overridden
 76	    // Preserve the original wire values while allowing configurable warning offsets.
 77	    case firstWarning = "warning15"
 78	    case finalWarning = "warning5"
 79	}
 80	
 81	public struct PolicySnapshot: Codable {
 82	    public var configuration: ScheduleConfiguration
 83	    public var phase: PolicyPhase
 84	    public var bedtime: Date?
 85	    public var allowedAt: Date?
 86	    public var occurrenceID: String?
 87	    public var passwordConfigured: Bool
 88	    public var shutdownPending: Bool
 89	}
 90	
 91	public enum ScheduleEvaluator {
 92	    public static func evaluate(_ configuration: ScheduleConfiguration, now: Date,
 93	                                calendar: Calendar = .autoupdatingCurrent,
 94	                                overrideID: String? = nil) -> PolicySnapshot {
 95	        var snapshot = PolicySnapshot(configuration: configuration, phase: .allowed,
 96	                                      passwordConfigured: false, shutdownPending: false)
 97	        guard configuration.enabled else { return snapshot }
 98	        let today = calendar.startOfDay(for: now)
 99	        // Yesterday catches overnight restrictions; eight days finds the next weekly start.
100	        for offset in -1...8 {
101	            guard let day = calendar.date(byAdding: .day, value: offset, to: today),
102	                  configuration.activeWeekdays.contains(calendar.component(.weekday, from: day)),
103	                  let start = time(configuration.bedtimeHour, configuration.bedtimeMinute,
104	                                   on: day, calendar: calendar) else { continue }
105	            let overnight = configuration.allowedHour * 60 + configuration.allowedMinute
106	                < configuration.bedtimeHour * 60 + configuration.bedtimeMinute
107	            guard let endDay = calendar.date(byAdding: .day, value: overnight ? 1 : 0, to: day),
108	                  let end = time(configuration.allowedHour, configuration.allowedMinute,
109	                                 on: endDay, calendar: calendar), end > start, end > now else { continue }
110	            let id = String(Int(start.timeIntervalSince1970))
111	            snapshot.bedtime = start
112	            snapshot.allowedAt = end
113	            snapshot.occurrenceID = id
114	            if now >= start {
115	                snapshot.phase = overrideID == id ? .overridden : .blocked
116	            } else if start.timeIntervalSince(now) <= Double(configuration.finalWarningSeconds) {
117	                snapshot.phase = .finalWarning
118	            } else if start.timeIntervalSince(now) <= Double(configuration.firstWarningSeconds) {
119	                snapshot.phase = .firstWarning
120	            }
121	            return snapshot
122	        }
123	        return snapshot
124	    }
125	
126	    private static func time(_ hour: Int, _ minute: Int, on day: Date,
127	                             calendar: Calendar) -> Date? {
128	        // Missing DST times advance to the next valid time; repeated times use the first.
129	        calendar.date(bySettingHour: hour, minute: minute, second: 0, of: day,
130	                      matchingPolicy: .nextTime, repeatedTimePolicy: .first, direction: .forward)
131	    }
132	}
133	
134	@objc public protocol BedtimeServiceProtocol {
135	    func snapshot(reply: @escaping (Data?, String?) -> Void)
136	    func updateConfiguration(_ data: Data, password: String?, reply: @escaping (String?) -> Void)
137	    func setPassword(_ password: String, currentPassword: String?, reply: @escaping (String?) -> Void)
138	    func unlock(_ password: String, reply: @escaping (String?) -> Void)
139	    func acknowledgeShutdown(_ occurrenceID: String, reply: @escaping (String?) -> Void)
140	}

