  1	import AppKit
  2	import BedtimeCore
  3	import SwiftUI
  4	
  5	private final class BannerWindow: NSWindow {
  6	    override var canBecomeKey: Bool { true }
  7	    override var canBecomeMain: Bool { true }
  8	}
  9	
 10	@MainActor final class OverlayController {
 11	    private let model: AppModel
 12	    private var windows: [NSWindow] = []
 13	    private var displayFrames: [NSRect] = []
 14	    private var observers: [NSObjectProtocol] = []
 15	    private var eventMonitor: Any?
 16	    private var showingBlock = false
 17	
 18	    init(model: AppModel) {
 19	        self.model = model
 20	        observers.append(NotificationCenter.default.addObserver(
 21	            forName: NSApplication.didChangeScreenParametersNotification, object: nil, queue: .main
 22	        ) { [weak self] _ in
 23	            Task { @MainActor in self?.synchronize(forceRebuild: true) }
 24	        })
 25	        for name in [NSWorkspace.didWakeNotification, NSWorkspace.sessionDidBecomeActiveNotification] {
 26	            observers.append(NSWorkspace.shared.notificationCenter.addObserver(
 27	                forName: name, object: nil, queue: .main
 28	            ) { [weak model] _ in
 29	                Task { @MainActor in await model?.refresh() }
 30	            })
 31	        }
 32	        eventMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { [weak self] event in
 33	            guard let self else { return event }
 34	            if self.model.blocked, !self.model.preview {
 35	                // Only events delivered to our own app. This is not a system-wide keyboard hook.
 36	                if event.keyCode == 53 || (event.modifierFlags.contains(.command)
 37	                    && ["q", "w", "h", "m"].contains(event.charactersIgnoringModifiers?.lowercased() ?? "")) {
 38	                    return nil
 39	                }
 40	            } else if event.keyCode == 53 {
 41	                self.model.dismissWarning()
 42	                return nil
 43	            }
 44	            return event
 45	        }
 46	    }
 47	
 48	    func synchronize(forceRebuild: Bool = false) {
 49	        guard model.bannerVisible else {
 50	            windows.forEach { $0.orderOut(nil) }
 51	            showingBlock = false
 52	            NSApp.presentationOptions = []
 53	            return
 54	        }
 55	        let blocking = model.blocked && !model.preview
 56	        if blocking { model.hideSettings() }
 57	        let frames = NSScreen.screens.map(\.frame)
 58	        if forceRebuild || windows.isEmpty || frames != displayFrames {
 59	            windows.forEach { $0.close() }
 60	            displayFrames = frames
 61	            windows = NSScreen.screens.map { screen in
 62	                let window = BannerWindow(contentRect: screen.frame, styleMask: .borderless,
 63	                                          backing: .buffered, defer: false)
 64	                window.setFrame(screen.frame, display: true)
 65	                window.level = .screenSaver
 66	                window.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary, .stationary]
 67	                window.isOpaque = true
 68	                window.backgroundColor = .black
 69	                window.hidesOnDeactivate = false
 70	                window.isReleasedWhenClosed = false
 71	                window.contentView = NSHostingView(rootView: BannerView(model: model))
 72	                return window
 73	            }
 74	        }
 75	        let wasVisible = windows.contains { $0.isVisible }
 76	        windows.forEach { $0.orderFrontRegardless() }
 77	        if !wasVisible || (blocking && (!showingBlock || !NSApp.isActive)) {
 78	            NSApp.activate(ignoringOtherApps: true)
 79	            windows.first?.makeKeyAndOrderFront(nil)
 80	        }
 81	        if blocking && !model.development {
 82	            NSApp.presentationOptions = [.hideDock, .hideMenuBar, .disableAppleMenu,
 83	                                         .disableProcessSwitching, .disableForceQuit,
 84	                                         .disableHideApplication]
 85	        } else {
 86	            NSApp.presentationOptions = []
 87	        }
 88	        showingBlock = blocking
 89	    }
 90	
 91	    /// Render our own UI offscreen: no screen recording, service installation, or shutdown.
 92	    static func renderPreview(to output: URL, blocked: Bool) throws {
 93	        let model = AppModel.shared
 94	        model.snapshot = ScheduleEvaluator.evaluate(.init(enabled: true, activeWeekdays: Array(1...7)), now: Date())
 95	        model.snapshot?.phase = blocked ? .blocked : .firstWarning
 96	        model.preview = !blocked
 97	        model.previewDeadline = Date().addingTimeInterval(900)
 98	        try PreviewRenderer.render(BannerView(model: model), size: NSSize(width: 1280, height: 720), to: output)
 99	    }
100	}
101	
102	private struct BannerView: View {
103	    @ObservedObject var model: AppModel
104	    @State private var password = ""
105	    @FocusState private var passwordFocused: Bool
106	    private var blocking: Bool { model.blocked && !model.preview }
107	    private var reminder: Reminder? { blocking || model.preview ? nil : model.activeReminder }
108	    private var deadline: Date? {
109	        blocking ? model.snapshot?.allowedAt
110	            : model.preview ? model.previewDeadline : reminder?.eventDate ?? model.snapshot?.bedtime
111	    }
112	    private var warningDescription: String {
113	        let seconds = model.snapshot?.phase == .finalWarning
114	            ? model.snapshot?.configuration.finalWarningSeconds
115	            : model.snapshot?.configuration.firstWarningSeconds
116	        return "\(model.duration(seconds ?? 900)) or less remain. Acknowledging does not postpone shutdown."
117	    }
118	
119	    var body: some View {
120	        OverlaySurface(appearance: model.appearance) { panel }
121	        .onChange(of: blocking) { value in password = ""; passwordFocused = value }
122	        .onAppear { passwordFocused = blocking }
123	    }
124	    private var panel: some View {
125	            VStack(spacing: 24) {
126	                HStack {
127	                    Label("BEDTIME", systemImage: "moon.zzz.fill")
128	                        .font(.headline).tracking(3)
129	                    Spacer()
130	                    TimelineView(.periodic(from: .now, by: 1)) { context in
131	                        Text(context.date, style: .time).monospacedDigit()
132	                    }
133	                }
134	                Text(blocking ? "Time to rest." : reminder?.displayTitle ?? "Your day is winding down.")
135	                    .font(.system(size: 54 * model.appearance.fontScale, weight: .bold)).minimumScaleFactor(0.5)
136	                    .accessibilityAddTraits(.isHeader)
137	                Text(blocking
138	                     ? "Access is paused until \(model.clock(model.snapshot?.allowedAt))."
139	                     : reminder.map { "Coming up at \(model.clock($0.eventDate))." }
140	                        ?? "Shutdown at \(model.clock(model.preview ? model.previewDeadline : model.snapshot?.bedtime)). Save your work.")
141	                    .font(.system(size: 26 * model.appearance.fontScale, weight: .semibold))
142	                if let deadline {
143	                    TimelineView(.periodic(from: .now, by: 1)) { context in
144	                        VStack(spacing: 5) {
145	                            Text(Countdown.text(until: deadline, now: context.date))
146	                                .font(.system(size: 44, weight: .semibold, design: .monospaced))
147	                            Text(blocking ? "until access resumes" : reminder != nil ? "until your event" : "until shutdown")
148	                                .font(.caption)
149	                        }
150	                    }
151	                }
152	                if blocking {
153	                    Text(model.development ? "Preview build: shutdown is disabled."
154	                         : model.shutdownMessage.isEmpty
155	                         ? "Your screen remains blocked even if graceful shutdown is cancelled."
156	                         : model.shutdownMessage)
157	                    if let error = model.error {
158	                        Text("Background service unavailable. The block stays active. \(error)")
159	                            .foregroundStyle(.yellow)
160	                    }
161	                    PasswordInput(placeholder: "Override passphrase", text: $password)
162	                        .focused($passwordFocused)
163	                        .onSubmit { unlock() }
164	                        .frame(maxWidth: 440)
165	                    HStack {
166	                        Button("Unlock until \(model.clock(model.snapshot?.allowedAt))") { unlock() }
167	                            .buttonStyle(OverlayButtonStyle(appearance: model.appearance))
168	                            .disabled(model.busy || password.isEmpty)
169	                            .opacity(model.busy || password.isEmpty ? 0.5 : 1)
170	                        if model.busy { ProgressView().controlSize(.small) }
171	                    }
172	                    if let error = model.unlockError {
173	                        Text(error).foregroundStyle(.yellow).accessibilityLabel("Unlock failed. \(error)")
174	                    }
175	                    if model.development {
176	                        Button("Quit preview build") { NSApp.terminate(nil) }
177	                            .buttonStyle(OverlayButtonStyle(appearance: model.appearance, primary: false))
178	                    }
179	                } else if let reminder {
180	                    if !reminder.notes.isEmpty { Text(reminder.notes).font(.title3) }
181	                    Button("Got it") { model.dismissWarning() }.buttonStyle(OverlayButtonStyle(appearance: model.appearance))
182	                } else {
183	                    Text(model.preview ? "This is a preview. No shutdown will occur."
184	                         : warningDescription)
185	                    Button(model.preview ? "Close preview" : "I’ll save my work") {
186	                        model.dismissWarning()
187	                    }.buttonStyle(OverlayButtonStyle(appearance: model.appearance))
188	                }
189	            }
190	            .multilineTextAlignment(.center)
191	    }
192	    private func unlock() {
193	        let submitted = password
194	        password = ""
195	        Task { await model.unlock(submitted) }
196	    }
197	}

