 7	private let log = Logger(subsystem: "com.ntfy.bedtime", category: "daemon")
 8	
 9	final class Service: NSObject, BedtimeServiceProtocol {
10	    private let store: PolicyStore
11	    private let queue = DispatchQueue(label: "com.ntfy.bedtime.policy")
12	    init(store: PolicyStore) { self.store = store }
13	
14	    func snapshot(reply: @escaping (Data?, String?) -> Void) {
15	        queue.async {
16	            do { reply(try JSONEncoder().encode(self.store.snapshot()), nil) }
17	            catch { reply(nil, error.localizedDescription) }
18	        }
19	    }
20	
21	    private func perform(_ reply: @escaping (String?) -> Void, action: @escaping () throws -> Void) {
22	        queue.async {
23	            do { try action(); reply(nil) }
24	            catch { reply(error.localizedDescription) }
25	        }
26	    }
27	
28	    func updateConfiguration(_ data: Data, password: String?, reply: @escaping (String?) -> Void) {
29	        perform(reply) {
30	            guard data.count < 4096 else { throw BedtimeError.message("Configuration is too large.") }
31	            try self.store.updateConfiguration(JSONDecoder().decode(ScheduleConfiguration.self, from: data),
32	                                               password: password)
33	        }
34	    }
35	    func setPassword(_ password: String, currentPassword: String?, reply: @escaping (String?) -> Void) {
36	        perform(reply) { try self.store.setPassword(password, currentPassword: currentPassword) }
37	    }
38	    func unlock(_ password: String, reply: @escaping (String?) -> Void) {
39	        perform(reply) { try self.store.unlock(password) }
40	    }
41	    func acknowledgeShutdown(_ occurrenceID: String, reply: @escaping (String?) -> Void) {
42	        perform(reply) { try self.store.acknowledgeShutdown(occurrenceID) }
43	    }
44	}
45	
46	final class ListenerDelegate: NSObject, NSXPCListenerDelegate {
47	    private let service: Service
48	    init(service: Service) {
49	        self.service = service
50	    }
51	
52	    func listener(_ listener: NSXPCListener, shouldAcceptNewConnection connection: NSXPCConnection) -> Bool {
53	        connection.exportedInterface = NSXPCInterface(with: BedtimeServiceProtocol.self)
54	        connection.exportedObject = service
55	        connection.resume()
56	        return true
57	    }
58	}
59	
60	do {
61	    guard geteuid() != 0 else { throw BedtimeError.message("Run Bedtime as your user's login service, never as root.") }
62	    let bundle = try ServicePaths.bundle(executable: ServicePaths.executablePath())
63	    let requirement = try SigningRequirements.peer(identifier: "com.ntfy.bedtime", at: bundle)
64	    let directory = ServicePaths.policyDirectory
65	    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true,
66	                                            attributes: [.posixPermissions: 0o700])
67	    let attributes = try FileManager.default.attributesOfItem(atPath: directory.path)
68	    guard attributes[.type] as? FileAttributeType == .typeDirectory,
69	          (attributes[.ownerAccountID] as? NSNumber)?.uint32Value == geteuid(),
70	          (attributes[.posixPermissions] as? NSNumber)?.intValue == 0o700 else {
71	        throw BedtimeError.message("Policy directory must belong to your account and have mode 0700.")
72	    }
73	    let service = Service(store: try PolicyStore(directory: directory))
74	    let delegate = ListenerDelegate(service: service)
75	    let listener = NSXPCListener(machServiceName: BedtimeConstants.machServiceName)
76	    listener.setConnectionCodeSigningRequirement(requirement)
77	    listener.delegate = delegate
78	    listener.resume()
79	    log.info("Policy service started.")
80	    withExtendedLifetime(delegate) { RunLoop.current.run() }
81	} catch {
82	    log.fault("Service could not start: \(error.localizedDescription, privacy: .public)")
83	    fputs("BedtimeDaemon: \(error.localizedDescription)\n", stderr)
84	    exit(1)
85	}

