 3	
 4	struct OnboardingView: View {
 5	    @ObservedObject var model: AppModel
 6	    @State private var password = ""
 7	    @State private var confirmation = ""
 8	    @State private var validation = ""
 9	
10	    var body: some View {
11	        VStack(alignment: .leading, spacing: 16) {
12	            setupContent
13	            HStack {
14	                Button("Set up later") { model.settingsTab = .general }
