16	                Text("Next: choose your times in Schedule.").font(.caption).foregroundStyle(.secondary)
17	                Button("Done") { model.settingsTab = .general }
18	                    .buttonStyle(.borderedProminent).disabled(model.needsSetup)
19	            }
20	        }
21	        .padding(28).frame(width: 840)
22	        .background(Color(nsColor: .windowBackgroundColor))
23	        .tint(.orange)
24	        .onDisappear { password = ""; confirmation = "" }
25	    }
26	
27	    private var setupContent: some View {
28	        VStack(alignment: .leading, spacing: 16) {
29	            Label("Welcome to Bedtime", systemImage: "moon.stars").font(.largeTitle.bold())
30	            Text("Three steps to get ready. You stay in control: setup never enables a schedule or shuts down your Mac.")
31	                .foregroundStyle(.secondary)
32	            if model.development {
33	                Text("This is a preview build. Install the local build to enable background protection and request Automation permission.")
34	            } else {
35	                step("1", title: "Keep Bedtime running", complete: model.servicesReady) {
36	                    Text("Install the scheduler and login agent, then allow Bedtime under System Settings → General → Login Items.")
37	                    HStack {
38	                        Button("Install / approve background items") { Task { await model.registerServices() } }
39	                            .disabled(model.launchBusy || model.servicesReady)
40	                        Button("Open Login Items") { model.openLoginItems() }
41	                    }
42	                }
43	                step("2", title: "Allow graceful shutdown", complete: model.automationGranted) {
44	                    Text("Allow Bedtime to control System Events. This requests permission only; it does not test shutdown.")
45	                    HStack {
46	                        Button(model.permissionBusy ? "Checking…" : "Request Automation permission") {
47	                            model.checkAutomationPermission(request: true)
48	                        }.disabled(model.permissionBusy || model.automationGranted)
49	                        Button("Open Automation settings") { model.openAutomationSettings() }
50	                        Button("Check again") { model.checkAutomationPermission() }
51	                            .disabled(model.permissionBusy)
52	                    }
53	                    if model.automationDenied {
54	                        Text("Permission is off. Enable Bedtime → System Events in Automation settings, then check again.")
55	                            .font(.caption).foregroundStyle(.secondary)
56	                    }
57	                }
58	                step("3", title: "Set your override passphrase", complete: model.snapshot?.passwordConfigured == true) {
59	                    if model.snapshot?.passwordConfigured != true {
60	                        Text("Choose a long passphrase (at least 16 characters) to unlock during blocked hours.")
61	                        HStack(spacing: 12) {
62	                            PasswordInput(placeholder: "New override passphrase", text: $password)
63	                            PasswordInput(placeholder: "Repeat passphrase", text: $confirmation)
64	                        }
65	                        Button("Save passphrase") {
66	                            guard password == confirmation else { validation = "The passphrases do not match."; return }
67	                            validation = ""
68	                            Task {
69	                                if await model.setPassword(password, current: "") {
70	                                    password = ""; confirmation = ""
71	                                }
72	                            }
73	                        }.disabled(model.busy || !model.servicesReady || model.snapshot == nil || password.count < 16)
74	                    } else {
75	                        Text("Your override passphrase is configured. You can change it in Security.")
76	                    }
77	                }
78	            }
79	            if let error = model.operationError ?? model.error {
80	                Text(error).font(.caption).foregroundStyle(.red).textSelection(.enabled)
81	            }
82	            if !validation.isEmpty { Text(validation).foregroundStyle(.red) }
83	        }
84	    }
