91	                    .foregroundStyle(complete ? Color.green : Color.orange)
92	                Text(title).font(.headline)
93	                Spacer()
94	                if complete { Text("Ready").font(.caption).foregroundStyle(.secondary) }
95	            }
96	            content()
97	        }
98	    }
99	}

